def max_potholes(road: str, budget: int) -> int:
    n = len(road)
    # blocks[length] = number of maximal pothole blocks of that length
    blocks = [0] * (n + 1)
    run = 0
    for ch in road + ".":
        if ch == "x":
            run += 1
        elif run:
            blocks[run] += 1
            run = 0
    fixed = 0
    for length in range(n, 0, -1):
        for _ in range(blocks[length]):
            if budget >= length + 1:
                fixed += length
                budget -= length + 1
            else:
                # Spend what is left on part of this block and stop.
                return fixed + max(budget - 1, 0)
    return fixed

