def maximum_tastiness(price: List[int], k: int) -> int:
    prices = sorted(price)

    def can_pick(gap: int) -> bool:
        # Greedily take the cheapest candy that keeps the gap.
        taken = 1
        last = prices[0]
        for p in prices:
            if p - last >= gap:
                taken += 1
                last = p
                if taken >= k:
                    return True
        return False

    lo, hi = 0, (prices[-1] - prices[0]) // (k - 1)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can_pick(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

