    # Count runs of identical characters by length.
    run_count = Counter()
    run = 1
    for i in range(1, n + 1):
        if i < n and s[i] == s[i - 1]:
            run += 1
        else:
            run_count[run] += 1
            run = 1
    longest = max(run_count)

