def max_power(stations: List[int], r: int, k: int) -> int:
    n = len(stations)
    prefix = [0] * (n + 1)
    for i, s in enumerate(stations):
        prefix[i + 1] = prefix[i] + s
    power = [prefix[min(n, i + r + 1)] - prefix[max(0, i - r)] for i in range(n)]

    def feasible(target: int) -> bool:
