            extra -= ends[i]
            short = target - power[i] - extra
            if short > 0:
                if short > left:
                    return False
                left -= short
                extra += short
                stop = i + 2 * r + 1        # stations placed at i + r help up to i + 2r
                if stop < n:
                    ends[stop] += short
        return True

    lo, hi = min(power), min(power) + k
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

