def champagne_tower(poured: int, query_row: int, query_glass: int) -> float:
    row = [float(poured)]                    # total liquid reaching each glass of this row
    for r in range(query_row):
        below = [0.0] * (r + 2)
        for j, amount in enumerate(row):
            if amount > 1.0:
                spill = (amount - 1.0) / 2.0
                below[j] += spill
                below[j + 1] += spill
        row = below
    return min(1.0, row[query_glass])

