class Codec:
    def serialize(self, root: Optional[TreeNode]) -> str:
        """Preorder values separated by commas; empty tree -> empty string."""
        out = []
        stack = [root] if root else []
        while stack:
            node = stack.pop()
            out.append(str(node.val))
            if node.right:
                stack.append(node.right)     # pushed first so left is visited first
            if node.left:
                stack.append(node.left)
        return ",".join(out)

    def deserialize(self, data: str) -> Optional[TreeNode]:
        if not data:
            return None
        values = [int(tok) for tok in data.split(",")]
        root = TreeNode(values[0])
        stack = [root]               # nodes whose right child is still open
        for v in values[1:]:
            node = TreeNode(v)
            parent = None
            while stack and stack[-1].val < v:
                parent = stack.pop()
            if parent is not None:
                parent.right = node
            else:
                stack[-1].left = node
            stack.append(node)
        return root

