def count_palindromic_subsequences(s: str) -> int:
    MOD = 10**9 + 7
    n = len(s)
    codes = [ord(ch) - 97 for ch in s]

    # flat tables: nxt[4 * i + c] is the first index >= i holding letter c (n if none),
    # prv[4 * (j + 1) + c] is the last index <= j holding letter c (-1 if none)
    nxt = [n] * (4 * (n + 1))
    for i in range(n - 1, -1, -1):
        nxt[4 * i:4 * i + 4] = nxt[4 * i + 4:4 * i + 8]
        nxt[4 * i + codes[i]] = i
    prv = [-1] * (4 * (n + 1))
    for j in range(n):
        prv[4 * j + 4:4 * j + 8] = prv[4 * j:4 * j + 4]
        prv[4 * j + 4 + codes[j]] = j

    memo = {}            # key i * n + j -> count for s[i..j]
    stack = [0 * n + (n - 1)]
    while stack:
        key = stack[-1]
        if key in memo:
            stack.pop()
            continue
        i, j = divmod(key, n)
        total, ready = 0, True
        for c in range(4):
            first, last = nxt[4 * i + c], prv[4 * (j + 1) + c]
            if first > j:
                continue                    # letter absent from s[i..j]
            if first == last:
                total += 1                  # just the single letter
            elif first + 1 > last - 1:
                total += 2                  # "c" and "cc"
            else:
                inner = (first + 1) * n + (last - 1)
                if inner in memo:
                    total += 2 + memo[inner]
                else:
                    ready = False
                    stack.append(inner)     # solve the inner range first
        if ready:
            memo[key] = total % MOD
            stack.pop()
    return memo[n - 1]

