def maximum_score(nums: list[int], max_val: int) -> int:
    top = max(max(nums), max_val)
    freq = [0] * (top + 1)
    for x in nums:
        freq[x] += 1

    # largest prime factor of every number up to top
    big_prime = [0] * (top + 1)
    for p in range(2, top + 1):
        if big_prime[p] == 0:
            big_prime[p::p] = [p] * len(range(p, top + 1, p))

    divisible = {}  # d -> how many elements are multiples of d

    def count_multiples(d):
        if d not in divisible:
            divisible[d] = sum(freq[d::d])
        return divisible[d]

    def distinct_primes(v):
        primes = []
        while v > 1:
            p = big_prime[v]
            primes.append(p)
            while v % p == 0:
                v //= p
        return primes

    def share(primes):
        """Number of elements divisible by at least one of the primes (inclusion exclusion)."""
        terms = [(1, -1)]  # (squarefree divisor, sign of its term)
        total = 0
        for p in primes:
            for d, sign in terms[:]:
                terms.append((d * p, -sign))
                total += -sign * count_multiples(d * p)
        return total

    best = 1 if freq[1] else 0  # writing a 1 somewhere always scores at least 0

    def consider(v, bonus):
        nonlocal best
        primes = distinct_primes(v)
        # cheap bound: share(v) is at least the count for its most common prime
        if v - max(count_multiples(p) for p in primes) + bonus <= best:
            return
        best = max(best, v - share(primes) + bonus)

    # keep an existing element v > 1 as the chosen one: score v - (share(v) - 1)
