        half = (length + 1) // 2
        for left in range(10 ** (half - 1), 10 ** half):
            text = str(left)
            # odd length shares the middle digit, even length mirrors all of it
            tail = text[-2::-1] if length % 2 else text[::-1]
            candidate = int(text + tail)
            if is_palindrome_in_base(candidate):
                total += candidate
                found += 1
                if found == n:
                    return total
        length += 1

def are_almost_equal(s1: str, s2: str) -> bool:
    diff = []
    for i, (a, b) in enumerate(zip(s1, s2)):
        if a != b:
            diff.append(i)
            if len(diff) > 2:
                return False
    if not diff:
        return True
    if len(diff) != 2:
        return False
    i, j = diff
    return s1[i] == s2[j] and s1[j] == s2[i]

def get_maximum_gold(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])

    def collect(r, c):
        gold = grid[r][c]
        grid[r][c] = 0  # mark as visited on the current path
        best_next = 0
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] > 0:
                best_next = max(best_next, collect(nr, nc))
        grid[r][c] = gold  # restore for other paths
        return gold + best_next

    best = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] > 0:
                best = max(best, collect(r, c))
    return best

def missing_element(nums: list[int], k: int) -> int:
    def missing(i):
        return nums[i] - nums[0] - i

    lo, hi = 0, len(nums) - 1
    # find the last index whose missing count is below k
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if missing(mid) < k:
            lo = mid
        else:
            hi = mid - 1
    return nums[lo] + k - missing(lo)
